 <!DOCTYPE html>
 <html lang="en">
 <head>
   <meta charset="UTF-8">
   <meta name="viewport" content="width=device-width, initial-scale=1.0">
   <title>Image Preview</title>
   <style>
     :root {
       color-scheme: dark;
       --bg: #0b1020;
       --panel: #131a2b;
       --panel-strong: #1a2338;
       --panel-border: #2a3654;
       --text: #f4f7fb;
       --muted: #a5b0c7;
       --accent: #8b5cf6;
       --accent-strong: #a78bfa;
       --danger: #ef4444;
       --danger-strong: #f87171;
       --shadow: 0 28px 80px rgba(0, 0, 0, 0.55);
       --focus: #c4b5fd;
     }

     * {
       box-sizing: border-box;
     }

     body {
       margin: 0;
       min-height: 100vh;
       font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
       background:
         radial-gradient(circle at top, rgba(139, 92, 246, 0.18), transparent 30%),
         linear-gradient(180deg, #0d1324 0%, var(--bg) 100%);
       color: var(--text);
       display: grid;
       place-items: center;
       padding: 24px;
     }

     button {
       font: inherit;
       border: 0;
       border-radius: 14px;
       cursor: pointer;
       transition: transform 0.18s ease, background-color 0.18s ease, border-color 0.18s ease;
     }

     button:hover {
       transform: translateY(-1px);
     }

     button:focus-visible {
       outline: 3px solid var(--focus);
       outline-offset: 3px;
     }

     .app-shell {
       width: min(100%, 920px);
     }

     .preview-card {
       background: linear-gradient(180deg, rgba(26, 35, 56, 0.94), rgba(19, 26, 43, 0.96));
       border: 1px solid rgba(167, 139, 250, 0.18);
       border-radius: 28px;
       overflow: hidden;
       box-shadow: var(--shadow);
     }

     .preview-layout {
       display: grid;
       grid-template-columns: minmax(0, 1.4fr) minmax(280px, 0.8fr);
     }

     .image-panel {
       padding: 28px;
       border-right: 1px solid rgba(167, 139, 250, 0.12);
     }

     .image-frame {
       aspect-ratio: 16 / 10;
       width: 100%;
       border-radius: 22px;
       overflow: hidden;
       border: 1px solid rgba(167, 139, 250, 0.18);
       background: #060913;
       box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.04);
     }

     .image-frame img {
       width: 100%;
       height: 100%;
       object-fit: cover;
       display: block;
     }

     .details-panel {
       padding: 32px 28px;
       display: flex;
       flex-direction: column;
       gap: 18px;
       justify-content: center;
     }

     .eyebrow {
       color: var(--accent-strong);
       font-size: 0.78rem;
       font-weight: 700;
       letter-spacing: 0.14em;
       text-transform: uppercase;
     }

     h1 {
       margin: 0;
       font-size: clamp(1.8rem, 4vw, 2.7rem);
       line-height: 1.05;
     }

     .meta {
       margin: 0;
       color: var(--muted);
       font-size: 1rem;
       line-height: 1.6;
     }

     .info-list {
       display: grid;
       grid-template-columns: repeat(2, minmax(0, 1fr));
       gap: 12px;
       margin: 4px 0 8px;
       padding: 0;
       list-style: none;
     }

     .info-list li {
       background: rgba(11, 16, 32, 0.72);
       border: 1px solid rgba(255, 255, 255, 0.06);
       border-radius: 16px;
       padding: 14px 16px;
     }

     .info-label {
       display: block;
       color: var(--muted);
       font-size: 0.84rem;
       margin-bottom: 4px;
     }

     .info-value {
       font-weight: 600;
     }

     .actions {
       display: flex;
       gap: 12px;
       flex-wrap: wrap;
       margin-top: 8px;
     }

     .button-secondary,
     .button-danger {
       min-height: 48px;
       padding: 0 18px;
       font-weight: 700;
     }

     .button-secondary {
       background: rgba(255, 255, 255, 0.04);
       color: var(--text);
       border: 1px solid rgba(255, 255, 255, 0.12);
     }

     .button-secondary:hover {
       background: rgba(255, 255, 255, 0.08);
     }

     .button-danger {
       background: linear-gradient(180deg, var(--danger-strong), var(--danger));
       color: #fff;
       box-shadow: 0 12px 30px rgba(239, 68, 68, 0.25);
     }

     dialog {
       padding: 0;
       width: min(calc(100vw - 32px), 460px);
       border: 1px solid rgba(167, 139, 250, 0.18);
       border-radius: 24px;
       background: linear-gradient(180deg, rgba(26, 35, 56, 0.98), rgba(19, 26, 43, 0.98));
       color: var(--text);
       box-shadow: var(--shadow);
     }

     dialog::backdrop {
       background: rgba(2, 6, 23, 0.7);
       backdrop-filter: blur(8px);
     }

     .dialog-content {
       padding: 28px;
     }

     .dialog-icon {
       width: 52px;
       height: 52px;
       display: inline-grid;
       place-items: center;
       border-radius: 16px;
       background: rgba(239, 68, 68, 0.14);
       color: #fecaca;
       margin-bottom: 18px;
       font-size: 1.35rem;
     }

     h2 {
       margin: 0 0 12px;
       font-size: 1.55rem;
     }

     .dialog-copy {
       margin: 0;
       color: var(--muted);
       line-height: 1.6;
     }

     .dialog-actions {
       display: flex;
       justify-content: flex-end;
       gap: 12px;
       margin-top: 28px;
       flex-wrap: wrap;
     }

     .sr-only {
       position: absolute;
       width: 1px;
       height: 1px;
       padding: 0;
       margin: -1px;
       overflow: hidden;
       clip: rect(0, 0, 0, 0);
       white-space: nowrap;
       border: 0;
     }

     @media (max-width: 760px) {
       .preview-layout {
         grid-template-columns: 1fr;
       }

       .image-panel {
         border-right: 0;
         border-bottom: 1px solid rgba(167, 139, 250, 0.12);
       }
     }

     @media (max-width: 480px) {
       body {
         padding: 16px;
       }

')
